"""Parsing of OKF markdown documents (frontmatter + body). Spec §4."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional

import yaml

FRONTMATTER_DELIMITER = re.compile(r"^---\s*$")

RESERVED_FILENAMES = frozenset({"index.md", "log.md"})


class FrontmatterError(Exception):
    """Raised when a frontmatter block is missing or malformed."""

    def __init__(self, code: str, message: str, line: Optional[int] = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.line = line


@dataclass
class Document:
    """A parsed markdown document: optional frontmatter mapping + body text."""

    frontmatter: Optional[Dict[str, Any]]
    body: str
    #: 1-indexed line where the body starts in the original file.
    body_start_line: int = 1
    #: Parse failure, if the document could not yield valid frontmatter.
    error: Optional[FrontmatterError] = None


def split_frontmatter(text: str):
    """Split raw file text into (frontmatter_text, body, body_start_line).

    ``frontmatter_text`` is ``None`` when the file has no frontmatter block.
    Raises :class:`FrontmatterError` for an unterminated block.
    """
    text = text.lstrip("﻿")
    lines = text.split("\n")
    if not lines or not FRONTMATTER_DELIMITER.match(lines[0]):
        return None, text, 1
    for i in range(1, len(lines)):
        if FRONTMATTER_DELIMITER.match(lines[i]):
            fm_text = "\n".join(lines[1:i])
            body = "\n".join(lines[i + 1 :])
            return fm_text, body, i + 2
    raise FrontmatterError(
        "unterminated-frontmatter",
        "frontmatter block opened with '---' but never closed",
        line=1,
    )


def parse_document(text: str, *, require_frontmatter: bool = True) -> Document:
    """Parse a document. Never raises; failures land in ``Document.error``."""
    try:
        fm_text, body, body_start = split_frontmatter(text)
    except FrontmatterError as exc:
        return Document(frontmatter=None, body="", error=exc)

    if fm_text is None:
        error = None
        if require_frontmatter:
            error = FrontmatterError(
                "missing-frontmatter",
                "document does not start with a '---' frontmatter block",
                line=1,
            )
        return Document(frontmatter=None, body=body, body_start_line=body_start, error=error)

    try:
        data = yaml.safe_load(fm_text)
    except yaml.YAMLError as exc:
        return Document(
            frontmatter=None,
            body=body,
            body_start_line=body_start,
            error=FrontmatterError("invalid-yaml", f"frontmatter is not valid YAML: {exc}", line=2),
        )

    if data is None:
        data = {}
    if not isinstance(data, dict):
        return Document(
            frontmatter=None,
            body=body,
            body_start_line=body_start,
            error=FrontmatterError(
                "frontmatter-not-mapping",
                f"frontmatter must be a YAML mapping, got {type(data).__name__}",
                line=2,
            ),
        )

    return Document(frontmatter=data, body=body, body_start_line=body_start)


def serialize_document(frontmatter: Optional[Dict[str, Any]], body: str) -> str:
    """Render frontmatter + body back to file text (round-trip helper)."""
    if frontmatter is None:
        return body
    fm_text = yaml.safe_dump(frontmatter, sort_keys=False, allow_unicode=True).rstrip("\n")
    return f"---\n{fm_text}\n---\n{body}"


def parse_timestamp(value: Any) -> Optional[datetime]:
    """Parse an ISO 8601 timestamp value; return None if unparseable."""
    if isinstance(value, datetime):
        return value
    if not isinstance(value, str):
        return None
    raw = value.strip()
    if raw.endswith(("Z", "z")):
        raw = raw[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(raw)
    except ValueError:
        return None


def title_from_filename(name: str) -> str:
    """Derive a display title from a filename per §4.1 ('consumers MAY')."""
    stem = name[:-3] if name.endswith(".md") else name
    stem = stem.rsplit("/", 1)[-1]
    words = re.split(r"[-_\s]+", stem)
    return " ".join(w[:1].upper() + w[1:] if w else w for w in words)

