"""Loading and traversal of OKF knowledge bundles. Spec §3."""

from __future__ import annotations

import posixpath
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Iterator, List, Optional

from .documents import (
    RESERVED_FILENAMES,
    Document,
    parse_document,
    parse_timestamp,
    title_from_filename,
)
from .links import Link, extract_links


@dataclass
class Concept:
    """A single unit of knowledge: one non-reserved markdown document. Spec §4."""

    concept_id: str  # path within the bundle, '.md' suffix removed
    path: str  # bundle-relative posix path, e.g. 'tables/orders.md'
    document: Document

    @property
    def frontmatter(self) -> Dict[str, Any]:
        return self.document.frontmatter or {}

    @property
    def body(self) -> str:
        return self.document.body

    @property
    def type(self) -> Optional[str]:
        value = self.frontmatter.get("type")
        return value if isinstance(value, str) and value.strip() else None

    @property
    def title(self) -> str:
        value = self.frontmatter.get("title")
        if isinstance(value, str) and value.strip():
            return value
        return title_from_filename(self.path)

    @property
    def description(self) -> Optional[str]:
        value = self.frontmatter.get("description")
        return value if isinstance(value, str) and value.strip() else None

    @property
    def resource(self) -> Optional[str]:
        value = self.frontmatter.get("resource")
        return value if isinstance(value, str) and value.strip() else None

    @property
    def tags(self) -> List[str]:
        value = self.frontmatter.get("tags")
        if isinstance(value, list):
            return [str(t) for t in value]
        return []

    @property
    def timestamp(self):
        return parse_timestamp(self.frontmatter.get("timestamp"))

    def links(self) -> List[Link]:
        """All markdown links in the body (excluding fenced code blocks)."""
        return extract_links(
            self.document.body,
            source_path=self.path,
            body_start_line=self.document.body_start_line,
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "concept_id": self.concept_id,
            "path": self.path,
            "type": self.type,
            "title": self.title,
            "description": self.description,
            "resource": self.resource,
            "tags": self.tags,
            "timestamp": self.frontmatter.get("timestamp"),
            "frontmatter": self.frontmatter,
        }


@dataclass
class ReservedFile:
    """A reserved ``index.md`` or ``log.md`` file. Spec §3.1, §6, §7."""

    path: str  # bundle-relative posix path
    document: Document


@dataclass
class Bundle:
    """A loaded knowledge bundle: a directory tree of markdown documents."""

    root: Path
    concepts: Dict[str, Concept] = field(default_factory=dict)
    indexes: Dict[str, ReservedFile] = field(default_factory=dict)  # keyed by directory
    logs: Dict[str, ReservedFile] = field(default_factory=dict)  # keyed by directory

    @classmethod
    def load(cls, root) -> "Bundle":
        """Load a bundle permissively — malformed documents are retained with
        their parse error attached, never rejected (§9)."""
        root_path = Path(root).resolve()
        if not root_path.is_dir():
            raise NotADirectoryError(f"bundle root is not a directory: {root_path}")
        bundle = cls(root=root_path)

        for file_path in sorted(root_path.rglob("*.md")):
            rel = file_path.relative_to(root_path).as_posix()
            if any(part.startswith(".") for part in rel.split("/")):
                continue
            text = file_path.read_text(encoding="utf-8")
            name = posixpath.basename(rel)
            directory = posixpath.dirname(rel)
            if name in RESERVED_FILENAMES:
                doc = parse_document(text, require_frontmatter=False)
                reserved = ReservedFile(path=rel, document=doc)
                if name == "index.md":
                    bundle.indexes[directory] = reserved
                else:
                    bundle.logs[directory] = reserved
            else:
                doc = parse_document(text, require_frontmatter=True)
                concept_id = rel[: -len(".md")]
                bundle.concepts[concept_id] = Concept(
                    concept_id=concept_id, path=rel, document=doc
                )
        return bundle

    @property
    def okf_version(self) -> Optional[str]:
        """OKF version declared in the bundle-root ``index.md`` frontmatter (§11)."""
        root_index = self.indexes.get("")
        if root_index and root_index.document.frontmatter:
            value = root_index.document.frontmatter.get("okf_version")
            if value is not None:
                return str(value)
        return None

    def get(self, concept_id: str) -> Optional[Concept]:
        return self.concepts.get(concept_id.strip("/"))

    def directories(self) -> List[str]:
        """All directories that contain at least one markdown document."""
        dirs = set()
        for path in self._all_paths():
            directory = posixpath.dirname(path)
            while True:
                dirs.add(directory)
                if not directory:
                    break
                directory = posixpath.dirname(directory)
        return sorted(dirs)

    def _all_paths(self) -> Iterator[str]:
        for concept in self.concepts.values():
            yield concept.path
        for reserved in list(self.indexes.values()) + list(self.logs.values()):
            yield reserved.path

    def iter_links(self) -> Iterator[tuple]:
        """Yield ``(concept, link)`` for every link in every concept body."""
        for concept in self.concepts.values():
            for link in concept.links():
                yield concept, link

    def resolve(self, link: Link) -> bool:
        """True if an internal link's target exists in the bundle (§5.3)."""
        if link.resolved is None:
            return False
        if link.concept_id is not None:
            if link.concept_id in self.concepts:
                return True
            # reserved files are valid link targets too
            return (self.root / link.resolved).is_file()
        target = self.root / link.resolved if link.resolved else self.root
        return target.exists()

    def broken_links(self) -> List[tuple]:
        """All internal links whose target does not exist in the bundle."""
        return [
            (concept, link)
            for concept, link in self.iter_links()
            if link.kind != "external" and not self.resolve(link)
        ]

