"""Conformance validation (§9) and soft-guidance linting for OKF bundles.

Errors are conformance violations — the bundle is not OKF v0.1 conformant.
Warnings are soft guidance and MUST NOT cause a consumer to reject a bundle.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date
from typing import Any, Dict, List, Optional

from .bundle import Bundle, ReservedFile
from .documents import parse_timestamp

ERROR = "error"
WARNING = "warning"

SUPPORTED_OKF_MAJOR = 0

DATE_HEADING = re.compile(r"^##\s+(.*?)\s*$")
ISO_DATE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


@dataclass
class Issue:
    severity: str  # ERROR | WARNING
    code: str
    path: str  # bundle-relative posix path ('' for bundle-level issues)
    message: str
    line: Optional[int] = None

    def __str__(self) -> str:
        location = self.path or "<bundle>"
        if self.line is not None:
            location += f":{self.line}"
        return f"{self.severity}: {location}: {self.message} [{self.code}]"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "severity": self.severity,
            "code": self.code,
            "path": self.path,
            "line": self.line,
            "message": self.message,
        }


@dataclass
class ValidationReport:
    issues: List[Issue] = field(default_factory=list)

    @property
    def errors(self) -> List[Issue]:
        return [i for i in self.issues if i.severity == ERROR]

    @property
    def warnings(self) -> List[Issue]:
        return [i for i in self.issues if i.severity == WARNING]

    @property
    def conformant(self) -> bool:
        return not self.errors

    def add(self, severity: str, code: str, path: str, message: str, line: Optional[int] = None):
        self.issues.append(Issue(severity, code, path, message, line))


def validate_bundle(bundle: Bundle) -> ValidationReport:
    report = ValidationReport()
    _check_version(bundle, report)
    for concept in bundle.concepts.values():
        _check_concept(concept, report)
    for directory, index in bundle.indexes.items():
        _check_index(index, is_root=(directory == ""), report=report)
    for log in bundle.logs.values():
        _check_log(log, report)
    _check_links(bundle, report)
    report.issues.sort(key=lambda i: (i.path, i.line or 0, i.code))
    return report


def _check_version(bundle: Bundle, report: ValidationReport) -> None:
    version = bundle.okf_version
    if version is None:
        return
    match = re.match(r"^(\d+)\.(\d+)$", version)
    root_index_path = bundle.indexes[""].path
    if not match:
        report.add(
            WARNING,
            "malformed-okf-version",
            root_index_path,
            f"okf_version {version!r} is not of the form <major>.<minor>",
        )
        return
    if int(match.group(1)) != SUPPORTED_OKF_MAJOR:
        report.add(
            WARNING,
            "unsupported-okf-version",
            root_index_path,
            f"bundle declares okf_version {version}; this tool implements 0.1 "
            "and will attempt best-effort consumption (§11)",
        )


def _check_concept(concept, report: ValidationReport) -> None:
    doc = concept.document
    if doc.error is not None:
        report.add(ERROR, doc.error.code, concept.path, doc.error.message, doc.error.line)
        return

    fm = doc.frontmatter or {}

    # §9.2 — required, non-empty `type`
    raw_type = fm.get("type")
    if raw_type is None:
        report.add(ERROR, "missing-type", concept.path, "frontmatter has no 'type' field")
    elif not isinstance(raw_type, str) or not raw_type.strip():
        report.add(
            ERROR,
            "invalid-type",
            concept.path,
            f"'type' must be a non-empty string, got {raw_type!r}",
        )

    # Recommended fields (§4.1) — soft guidance only
    for key in ("title", "description"):
        value = fm.get(key)
        if value is None:
            report.add(WARNING, f"missing-{key}", concept.path, f"recommended field '{key}' is absent")
        elif not isinstance(value, str) or not value.strip():
            report.add(
                WARNING, f"invalid-{key}", concept.path, f"'{key}' should be a non-empty string"
            )

    tags = fm.get("tags")
    if tags is not None and (
        not isinstance(tags, list) or not all(isinstance(t, (str, int, float)) for t in tags)
    ):
        report.add(WARNING, "invalid-tags", concept.path, "'tags' should be a YAML list of short strings")

    timestamp = fm.get("timestamp")
    if timestamp is not None and parse_timestamp(timestamp) is None:
        report.add(
            WARNING,
            "invalid-timestamp",
            concept.path,
            f"'timestamp' is not an ISO 8601 datetime: {timestamp!r}",
        )


def _check_index(index: ReservedFile, *, is_root: bool, report: ValidationReport) -> None:
    doc = index.document
    if doc.error is not None:
        report.add(ERROR, doc.error.code, index.path, doc.error.message, doc.error.line)
        return
    if doc.frontmatter is not None and not is_root:
        report.add(
            ERROR,
            "index-frontmatter",
            index.path,
            "index.md files must not contain frontmatter; it is permitted only "
            "in the bundle-root index.md to declare okf_version (§6, §11)",
            line=1,
        )


def _check_log(log: ReservedFile, report: ValidationReport) -> None:
    doc = log.document
    if doc.error is not None:
        report.add(ERROR, doc.error.code, log.path, doc.error.message, doc.error.line)
        return
    if doc.frontmatter is not None:
