class TestSplitFrontmatter:
    def test_basic_split(self):
        fm, body, start = split_frontmatter("---\ntype: Note\n---\nBody here.\n")
        assert fm == "type: Note"
        assert body == "Body here.\n"
        assert start == 4

    def test_no_frontmatter(self):
        fm, body, start = split_frontmatter("Just a body.\n")
        assert fm is None
        assert body == "Just a body.\n"
        assert start == 1

    def test_bom_is_stripped(self):
        fm, _, _ = split_frontmatter("﻿---\ntype: Note\n---\n")
        assert fm == "type: Note"

    def test_delimiter_allows_trailing_whitespace(self):
        fm, body, _ = split_frontmatter("---  \ntype: Note\n---\t\nBody\n")
        assert fm == "type: Note"
        assert body == "Body\n"

    def test_dashes_inside_body_not_treated_as_delimiter(self):
        text = "---\ntype: Note\n---\nBody\n---\nmore body\n"
        _, body, _ = split_frontmatter(text)
        assert "more body" in body

    def test_unterminated_raises(self):
        import pytest

        from okf.documents import FrontmatterError

        with pytest.raises(FrontmatterError) as exc_info:
            split_frontmatter("---\ntype: Note\nno closing delimiter\n")
        assert exc_info.value.code == "unterminated-frontmatter"


class TestParseDocument:
    def test_valid_document(self):
        doc = parse_document("---\ntype: Note\ntitle: T\n---\nBody\n")
        assert doc.error is None
        assert doc.frontmatter == {"type": "Note", "title": "T"}
        assert doc.body == "Body\n"

    def test_missing_frontmatter_is_error_when_required(self):
        doc = parse_document("no frontmatter\n", require_frontmatter=True)
        assert doc.error is not None
        assert doc.error.code == "missing-frontmatter"

    def test_missing_frontmatter_ok_when_not_required(self):
        doc = parse_document("# Index\n", require_frontmatter=False)
        assert doc.error is None
        assert doc.frontmatter is None
        assert doc.body == "# Index\n"

    def test_invalid_yaml(self):
        doc = parse_document("---\ntype: [unclosed\n---\nBody\n")
        assert doc.error is not None
        assert doc.error.code == "invalid-yaml"

    def test_non_mapping_frontmatter(self):
        doc = parse_document("---\n- a\n- b\n---\nBody\n")
        assert doc.error is not None
        assert doc.error.code == "frontmatter-not-mapping"

    def test_empty_frontmatter_is_empty_mapping(self):
        doc = parse_document("---\n---\nBody\n")
        assert doc.error is None
        assert doc.frontmatter == {}

    def test_unknown_keys_preserved(self):
        doc = parse_document("---\ntype: Note\nx_custom: [1, 2]\n---\n")
        assert doc.frontmatter["x_custom"] == [1, 2]

    def test_unterminated_frontmatter(self):
        doc = parse_document("---\ntype: Note\n")
        assert doc.error is not None
        assert doc.error.code == "unterminated-frontmatter"


class TestRoundTrip:
    def test_serialize_round_trips(self):
        original = "---\ntype: Note\ntitle: T\nx_custom: keep-me\n---\nBody line.\n"
        doc = parse_document(original)
        rebuilt = serialize_document(doc.frontmatter, doc.body)
        reparsed = parse_document(rebuilt)
        assert reparsed.frontmatter == doc.frontmatter
        assert reparsed.body == doc.body

    def test_serialize_without_frontmatter(self):
        assert serialize_document(None, "just body") == "just body"


class TestParseTimestamp:
    def test_zulu_suffix(self):
        parsed = parse_timestamp("2026-05-28T14:30:00Z")
        assert parsed == datetime(2026, 5, 28, 14, 30, tzinfo=timezone.utc)

    def test_offset(self):
        assert parse_timestamp("2026-05-28T14:30:00+02:00") is not None

    def test_date_only(self):
        assert parse_timestamp("2026-05-28") is not None

    def test_yaml_native_datetime_passthrough(self):
        native = datetime(2026, 1, 1)
        assert parse_timestamp(native) is native

    def test_garbage_returns_none(self):
        assert parse_timestamp("yesterday-ish") is None
        assert parse_timestamp(12345) is None


class TestTitleFromFilename:
    def test_dashes_and_underscores(self):
        assert title_from_filename("customer-metrics.md") == "Customer Metrics"
        assert title_from_filename("customer_metrics") == "Customer Metrics"

    def test_nested_path_uses_basename(self):
        assert title_from_filename("tables/orders.md") == "Orders"

