from okf.links import ABSOLUTE, EXTERNAL, RELATIVE, extract_links


def links_of(body, source="tables/orders.md", start=1):
    return extract_links(body, source_path=source, body_start_line=start)


class TestExtraction:
    def test_inline_link(self):
        (link,) = links_of("See [customers](/tables/customers.md) here.")
        assert link.text == "customers"
        assert link.target == "/tables/customers.md"

    def test_multiple_links_on_one_line(self):
        found = links_of("[a](/a.md) and [b](/b.md)")
        assert [l.target for l in found] == ["/a.md", "/b.md"]

    def test_line_numbers_account_for_frontmatter(self):
        body = "first line\n[x](/x.md)\n"
        (link,) = links_of(body, start=8)
        assert link.line == 9

    def test_links_in_fenced_code_ignored(self):
        body = "```\n[not a link](/skip.md)\n```\n[real](/real.md)\n"
        found = links_of(body)
        assert [l.target for l in found] == ["/real.md"]

    def test_tilde_fence(self):
        body = "~~~\n[skip](/skip.md)\n~~~\n"
        assert links_of(body) == []

    def test_links_in_inline_code_ignored(self):
        body = "use `[x](/skip.md)` but also [y](/keep.md)"
        found = links_of(body)
        assert [l.target for l in found] == ["/keep.md"]

    def test_image_flagged(self):
        (link,) = links_of("![diagram](/img/erd.png)")
        assert link.is_image

    def test_angle_bracket_target(self):
        (link,) = links_of("[spaced](</tables/order history.md>)")
        assert link.target == "/tables/order history.md"
        assert link.concept_id == "tables/order history"

    def test_title_after_target(self):
        (link,) = links_of('[t](/tables/customers.md "hover title")')
        assert link.target == "/tables/customers.md"


class TestClassification:
    def test_external_schemes(self):
        for target in ("https://example.com/x", "mailto:a@b.c", "bq://acme.sales.orders"):
            (link,) = links_of(f"[x]({target})")
            assert link.kind == EXTERNAL
            assert link.resolved is None

    def test_absolute_bundle_relative(self):
        (link,) = links_of("[x](/datasets/sales.md)")
        assert link.kind == ABSOLUTE
        assert link.resolved == "datasets/sales.md"
        assert link.concept_id == "datasets/sales"

    def test_relative_same_directory(self):
        (link,) = links_of("[x](./customers.md)")
        assert link.kind == RELATIVE
        assert link.resolved == "tables/customers.md"
        assert link.concept_id == "tables/customers"

    def test_relative_parent_directory(self):
        (link,) = links_of("[x](../datasets/sales.md)")
        assert link.resolved == "datasets/sales.md"

    def test_relative_escaping_bundle(self):
        (link,) = links_of("[x](../../outside.md)")
        assert link.resolved is None
        assert link.escapes_bundle

    def test_fragment_stripped_for_resolution(self):
        (link,) = links_of("[x](/tables/customers.md#schema)")
        assert link.resolved == "tables/customers.md"
        assert link.concept_id == "tables/customers"

    def test_directory_link(self):
        (link,) = links_of("[x](/playbooks/)")
        assert link.resolved == "playbooks"
        assert link.concept_id is None

    def test_non_md_target_has_no_concept_id(self):
        (link,) = links_of("[x](/schemas/orders.avsc)")
        assert link.resolved == "schemas/orders.avsc"
        assert link.concept_id is None

