from okf.bundle import Bundle

from conftest import concept


class TestLoad:
    def test_loads_example_bundle(self, example_bundle_path):
        bundle = Bundle.load(example_bundle_path)
        assert set(bundle.concepts) == {
            "datasets/sales",
            "tables/orders",
            "tables/customers",
            "playbooks/freshness",
        }
        assert "" in bundle.indexes
        assert "" in bundle.logs
        assert bundle.okf_version == "0.1"

    def test_concept_id_is_path_without_suffix(self, make_bundle):
        root = make_bundle({"a/b/deep.md": concept()})
        bundle = Bundle.load(root)
        assert bundle.get("a/b/deep").path == "a/b/deep.md"

    def test_reserved_files_are_not_concepts(self, make_bundle):
        root = make_bundle(
            {
                "index.md": "# Contents\n",
                "log.md": "# Log\n",
                "note.md": concept(),
            }
        )
        bundle = Bundle.load(root)
        assert set(bundle.concepts) == {"note"}
        assert set(bundle.indexes) == {""}
        assert set(bundle.logs) == {""}

    def test_hidden_directories_skipped(self, make_bundle):
        root = make_bundle(
            {
                "note.md": concept(),
                ".git/objects/fake.md": "not markdown frontmatter",
                ".obsidian/config.md": "x",
            }
        )
        bundle = Bundle.load(root)
        assert set(bundle.concepts) == {"note"}

    def test_malformed_concept_is_kept_with_error(self, make_bundle):
        root = make_bundle({"bad.md": "no frontmatter here\n"})
        bundle = Bundle.load(root)
        bad = bundle.get("bad")
        assert bad is not None
        assert bad.document.error.code == "missing-frontmatter"

    def test_nonexistent_root_raises(self, tmp_path):
        import pytest

        with pytest.raises(NotADirectoryError):
            Bundle.load(tmp_path / "missing")


class TestConceptProperties:
    def test_title_falls_back_to_filename(self, make_bundle):
        root = make_bundle({"customer-metrics.md": "---\ntype: Note\n---\nBody\n"})
        c = Bundle.load(root).get("customer-metrics")
        assert c.title == "Customer Metrics"

    def test_graceful_on_malformed_fields(self, make_bundle):
        root = make_bundle(
            {"odd.md": "---\ntype: 42\ntitle: [not, a, string]\ntags: nope\n---\n"}
        )
        c = Bundle.load(root).get("odd")
        assert c.type is None  # non-string type is not usable
        assert c.title == "Odd"  # falls back to filename
        assert c.tags == []

    def test_to_dict_includes_frontmatter_extensions(self, make_bundle):
        root = make_bundle({"n.md": "---\ntype: Note\nx_owner: data-team\n---\n"})
        payload = Bundle.load(root).get("n").to_dict()
        assert payload["frontmatter"]["x_owner"] == "data-team"


class TestLinksAndResolution:
    def test_iter_links_covers_all_concepts(self, example_bundle_path):
        bundle = Bundle.load(example_bundle_path)
        sources = {c.concept_id for c, _ in bundle.iter_links()}
        assert "datasets/sales" in sources
        assert "playbooks/freshness" in sources

    def test_example_bundle_has_no_broken_links(self, example_bundle_path):
        bundle = Bundle.load(example_bundle_path)
        assert bundle.broken_links() == []

    def test_broken_link_detected(self, make_bundle):
        root = make_bundle(
            {"a.md": concept(body="See [ghost](/missing/ghost.md).")}
        )
        bundle = Bundle.load(root)
        broken = bundle.broken_links()
        assert len(broken) == 1
        assert broken[0][1].concept_id == "missing/ghost"

    def test_link_to_reserved_file_resolves(self, make_bundle):
        root = make_bundle(
            {
                "index.md": "# Contents\n",
                "a.md": concept(body="See the [index](/index.md)."),
            }
        )
        assert Bundle.load(root).broken_links() == []

    def test_link_to_directory_resolves(self, make_bundle):
        root = make_bundle(
            {
                "a.md": concept(body="Browse [tables](/tables/)."),
                "tables/t.md": concept(),
            }
        )
        assert Bundle.load(root).broken_links() == []


class TestDirectories:
    def test_directories_include_intermediate_levels(self, make_bundle):
        root = make_bundle({"a/b/c.md": concept()})
        assert Bundle.load(root).directories() == ["", "a", "a/b"]

