class TestConformance:
    def test_example_bundle_is_conformant(self, example_bundle_path):
        report = validate_bundle(Bundle.load(example_bundle_path))
        assert report.conformant, [str(i) for i in report.errors]
        assert report.warnings == []

    def test_missing_frontmatter_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "just prose\n"})
        assert "missing-frontmatter" in codes(report, "error")
        assert not report.conformant

    def test_unterminated_frontmatter_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "---\ntype: Note\n"})
        assert "unterminated-frontmatter" in codes(report, "error")

    def test_invalid_yaml_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "---\ntype: [oops\n---\n"})
        assert "invalid-yaml" in codes(report, "error")

    def test_missing_type_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "---\ntitle: No Type\n---\n"})
        assert "missing-type" in codes(report, "error")

    def test_empty_type_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "---\ntype: '  '\n---\n"})
        assert "invalid-type" in codes(report, "error")

    def test_non_string_type_is_error(self, make_bundle):
        report = validate(make_bundle, {"bad.md": "---\ntype: [a, b]\n---\n"})
        assert "invalid-type" in codes(report, "error")

