    def test_unknown_frontmatter_keys_are_fine(self, make_bundle):
        report = validate(
            make_bundle,
            {
                "c.md": "---\ntype: Note\ntitle: T\ndescription: D\nx_extra: 1\n---\nB\n"
            },
        )
        assert report.conformant
        assert "x_extra" not in " ".join(codes(report))


