"""``okf`` — command-line interface for the Open Knowledge Format."""

from __future__ import annotations

import argparse
import json
import sys
from typing import List, Optional

from .bundle import Bundle
from .indexing import write_indexes
from .validation import validate_bundle

EXIT_OK = 0
EXIT_ISSUES = 1
EXIT_USAGE = 2


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        bundle = Bundle.load(args.bundle)
    except (NotADirectoryError, OSError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return EXIT_USAGE
    return args.func(args, bundle)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="okf",
        description="Reference tooling for Open Knowledge Format (OKF) v0.1 bundles.",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    def add(name: str, help_text: str, func):
        cmd = sub.add_parser(name, help=help_text)
        cmd.add_argument("bundle", nargs="?", default=".", help="bundle root (default: .)")
        cmd.add_argument("--json", action="store_true", help="emit machine-readable JSON")
        cmd.set_defaults(func=func)
        return cmd

    validate = add("validate", "check §9 conformance and report soft-guidance warnings", cmd_validate)
    validate.add_argument(
        "--strict", action="store_true", help="treat warnings as failures (exit 1)"
    )
    validate.add_argument(
        "--errors-only", action="store_true", help="suppress warnings in the output"
    )

    list_cmd = add("list", "list concepts in the bundle", cmd_list)
    list_cmd.add_argument("--type", dest="type_filter", help="only concepts of this type")
    list_cmd.add_argument("--tag", dest="tag_filter", help="only concepts carrying this tag")

    show = add("show", "print one concept (frontmatter + body)", cmd_show)
    show.add_argument("concept_id", help="concept ID, e.g. tables/orders")

    links = add("links", "report the cross-link graph", cmd_links)
    links.add_argument("--broken", action="store_true", help="only links with missing targets")

    index = add("index", "generate index.md files for progressive disclosure (§6)", cmd_index)
    index.add_argument(
        "--check",
        action="store_true",
        help="don't write; exit 1 if any index.md is missing or stale",
    )

    return parser


def cmd_validate(args, bundle: Bundle) -> int:
    report = validate_bundle(bundle)
    issues = report.errors if args.errors_only else report.issues
    failed = bool(report.errors) or (args.strict and bool(report.warnings))

    if args.json:
        print(
            json.dumps(
                {
                    "conformant": report.conformant,
                    "okf_version": bundle.okf_version,
                    "concepts": len(bundle.concepts),
                    "errors": [i.to_dict() for i in report.errors],
                    "warnings": [] if args.errors_only else [i.to_dict() for i in report.warnings],
                },
                indent=2,
            )
        )
        return EXIT_ISSUES if failed else EXIT_OK

    for issue in issues:
        print(issue)
    verdict = "conformant" if report.conformant else "NOT conformant"
    print(
        f"{bundle.root}: {verdict} with OKF v0.1 — "
        f"{len(bundle.concepts)} concept(s), "
        f"{len(report.errors)} error(s), {len(report.warnings)} warning(s)"
    )
    return EXIT_ISSUES if failed else EXIT_OK


def cmd_list(args, bundle: Bundle) -> int:
    concepts = sorted(bundle.concepts.values(), key=lambda c: c.concept_id)
    if args.type_filter:
        concepts = [c for c in concepts if c.type == args.type_filter]
    if args.tag_filter:
        concepts = [c for c in concepts if args.tag_filter in c.tags]

    if args.json:
        print(json.dumps([c.to_dict() for c in concepts], indent=2, default=str))
        return EXIT_OK
    for concept in concepts:
        type_label = concept.type or "?"
        desc = f" — {concept.description}" if concept.description else ""
        print(f"{concept.concept_id}  [{type_label}]  {concept.title}{desc}")
    return EXIT_OK


def cmd_show(args, bundle: Bundle) -> int:
    concept = bundle.get(args.concept_id)
    if concept is None:
        print(f"error: no concept with ID {args.concept_id!r}", file=sys.stderr)
        return EXIT_USAGE
    if args.json:
        payload = concept.to_dict()
        payload["body"] = concept.body
        payload["links"] = [
            {
                "text": l.text,
                "target": l.target,
                "kind": l.kind,
                "concept_id": l.concept_id,
                "line": l.line,
            }
            for l in concept.links()
        ]
        print(json.dumps(payload, indent=2, default=str))
        return EXIT_OK
    print((bundle.root / concept.path).read_text(encoding="utf-8"), end="")
    return EXIT_OK


def cmd_links(args, bundle: Bundle) -> int:
    rows = []
    for concept, link in bundle.iter_links():
        if link.kind == "external":
            continue
        ok = bundle.resolve(link)
        if args.broken and ok:
            continue
        rows.append((concept, link, ok))

    if args.json:
        print(
            json.dumps(
                [
                    {
                        "source": c.concept_id,
                        "target": l.concept_id or l.resolved,
                        "raw": l.target,
                        "line": l.line,
                        "kind": l.kind,
                        "broken": not ok,
                    }
                    for c, l, ok in rows
                ],
                indent=2,
            )
        )
    else:
        for concept, link, ok in rows:
            marker = "ok    " if ok else "BROKEN"
            print(f"{marker}  {concept.concept_id} -> {link.target}  ({concept.path}:{link.line})")
        if not rows:
            print("no matching internal links")
    return EXIT_ISSUES if args.broken and rows else EXIT_OK


def cmd_index(args, bundle: Bundle) -> int:
    changed = write_indexes(bundle, check=args.check)
    if args.json:
        print(json.dumps({"changed": changed, "check": args.check}, indent=2))
    else:
        verb = "stale" if args.check else "wrote"
        for path in changed:
            print(f"{verb}: {path}")
        if not changed:
            print("all index.md files up to date")
    return EXIT_ISSUES if args.check and changed else EXIT_OK


if __name__ == "__main__":
    sys.exit(main())

