        f"{len(report.errors)} error(s), {len(report.warnings)} warning(s)"
    )
    return EXIT_ISSUES if failed else EXIT_OK


def cmd_list(args, bundle: Bundle) -> int:
    concepts = sorted(bundle.concepts.values(), key=lambda c: c.concept_id)
    if args.type_filter:
        concepts = [c for c in concepts if c.type == args.type_filter]
    if args.tag_filter:
        concepts = [c for c in concepts if args.tag_filter in c.tags]

    if args.json:
        print(json.dumps([c.to_dict() for c in concepts], indent=2, default=str))
        return EXIT_OK
    for concept in concepts:
        type_label = concept.type or "?"
        desc = f" — {concept.description}" if concept.description else ""
        print(f"{concept.concept_id}  [{type_label}]  {concept.title}{desc}")
    return EXIT_OK


def cmd_show(args, bundle: Bundle) -> int:
    concept = bundle.get(args.concept_id)
    if concept is None:
        print(f"error: no concept with ID {args.concept_id!r}", file=sys.stderr)
        return EXIT_USAGE
    if args.json:
        payload = concept.to_dict()
        payload["body"] = concept.body
        payload["links"] = [
            {
                "text": l.text,
                "target": l.target,
                "kind": l.kind,
                "concept_id": l.concept_id,
                "line": l.line,
            }
            for l in concept.links()
        ]
        print(json.dumps(payload, indent=2, default=str))
        return EXIT_OK
    print((bundle.root / concept.path).read_text(encoding="utf-8"), end="")
    return EXIT_OK


def cmd_links(args, bundle: Bundle) -> int:
    rows = []
    for concept, link in bundle.iter_links():
        if link.kind == "external":
            continue
        ok = bundle.resolve(link)
        if args.broken and ok:
            continue
        rows.append((concept, link, ok))

    if args.json:
        print(
            json.dumps(
                [
                    {
                        "source": c.concept_id,
                        "target": l.concept_id or l.resolved,
                        "raw": l.target,
                        "line": l.line,
                        "kind": l.kind,
                        "broken": not ok,
                    }
                    for c, l, ok in rows
                ],
                indent=2,
            )
        )
    else:
        for concept, link, ok in rows:
            marker = "ok    " if ok else "BROKEN"
            print(f"{marker}  {concept.concept_id} -> {link.target}  ({concept.path}:{link.line})")
        if not rows:
            print("no matching internal links")
    return EXIT_ISSUES if args.broken and rows else EXIT_OK


def cmd_index(args, bundle: Bundle) -> int:
    changed = write_indexes(bundle, check=args.check)
    if args.json:
        print(json.dumps({"changed": changed, "check": args.check}, indent=2))
    else:
        verb = "stale" if args.check else "wrote"
        for path in changed:
            print(f"{verb}: {path}")
        if not changed:
            print("all index.md files up to date")
    return EXIT_ISSUES if args.check and changed else EXIT_OK


if __name__ == "__main__":
    sys.exit(main())

"""Parsing of OKF markdown documents (frontmatter + body). Spec §4."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional

import yaml

FRONTMATTER_DELIMITER = re.compile(r"^---\s*$")

RESERVED_FILENAMES = frozenset({"index.md", "log.md"})


class FrontmatterError(Exception):
    """Raised when a frontmatter block is missing or malformed."""

    def __init__(self, code: str, message: str, line: Optional[int] = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.line = line


@dataclass
class Document:
    """A parsed markdown document: optional frontmatter mapping + body text."""

    frontmatter: Optional[Dict[str, Any]]
    body: str
    #: 1-indexed line where the body starts in the original file.
    body_start_line: int = 1
    #: Parse failure, if the document could not yield valid frontmatter.
    error: Optional[FrontmatterError] = None


def split_frontmatter(text: str):
    """Split raw file text into (frontmatter_text, body, body_start_line).

    ``frontmatter_text`` is ``None`` when the file has no frontmatter block.
    Raises :class:`FrontmatterError` for an unterminated block.
    """
    text = text.lstrip("\ufeff")
    lines = text.split("\n")
    if not lines or not FRONTMATTER_DELIMITER.match(lines[0]):
        return None, text, 1
    for i in range(1, len(lines)):
        if FRONTMATTER_DELIMITER.match(lines[i]):
            fm_text = "\n".join(lines[1:i])
            body = "\n".join(lines[i + 1 :])
            return fm_text, body, i + 2
    raise FrontmatterError(
        "unterminated-frontmatter",
        "frontmatter block opened with '---' but never closed",
        line=1,
    )


def parse_document(text: str, *, require_frontmatter: bool = True) -> Document:
    """Parse a document. Never raises; failures land in ``Document.error``."""
    try:
        fm_text, body, body_start = split_frontmatter(text)
    except FrontmatterError as exc:
        return Document(frontmatter=None, body="", error=exc)

    if fm_text is None:
        error = None
        if require_frontmatter:
            error = FrontmatterError(
                "missing-frontmatter",
                "document does not start with a '---' frontmatter block",
                line=1,
            )
        return Document(frontmatter=None, body=body, body_start_line=body_start, error=error)

    try:
        data = yaml.safe_load(fm_text)
    except yaml.YAMLError as exc:
        return Document(
            frontmatter=None,
            body=body,
            body_start_line=body_start,
            error=FrontmatterError("invalid-yaml", f"frontmatter is not valid YAML: {exc}", line=2),
        )

    if data is None:
        data = {}
    if not isinstance(data, dict):
        return Document(
            frontmatter=None,
            body=body,
            body_start_line=body_start,
            error=FrontmatterError(
                "frontmatter-not-mapping",
                f"frontmatter must be a YAML mapping, got {type(data).__name__}",
                line=2,
            ),
        )

    return Document(frontmatter=data, body=body, body_start_line=body_start)


def serialize_document(frontmatter: Optional[Dict[str, Any]], body: str) -> str:
    """Render frontmatter + body back to file text (round-trip helper)."""
    if frontmatter is None:
        return body
    fm_text = yaml.safe_dump(frontmatter, sort_keys=False, allow_unicode=True).rstrip("\n")
    return f"---\n{fm_text}\n---\n{body}"


def parse_timestamp(value: Any) -> Optional[datetime]:
    """Parse an ISO 8601 timestamp value; return None if unparseable."""
    if isinstance(value, datetime):
        return value
    if not isinstance(value, str):
        return None
    raw = value.strip()
    if raw.endswith(("Z", "z")):
        raw = raw[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(raw)
    except ValueError:
        return None


def title_from_filename(name: str) -> str:
    """Derive a display title from a filename per §4.1 ('consumers MAY')."""
    stem = name[:-3] if name.endswith(".md") else name
    stem = stem.rsplit("/", 1)[-1]
    words = re.split(r"[-_\s]+", stem)
    return " ".join(w[:1].upper() + w[1:] if w else w for w in words)
